const $=id=>document.getElementById(id);
let catalog=[],current,frontMode='source',modelMode=false,viewer;
function showImages(){modelMode=false;$('comparison').hidden=false;$('model-panel').hidden=true;$('model-button').setAttribute('aria-pressed','false');viewer?.pause();renderFront();}
function renderFront(){if(!current)return;$('front').src=current[frontMode]||current.source;$('front-caption').textContent=frontMode==='source'?'原照切片 · 保留形态依据':'正面建模参考 · Hi3D 图片编辑';$('source-button').setAttribute('aria-pressed',String(frontMode==='source'));$('front-button').setAttribute('aria-pressed',String(frontMode==='front'));}
function select(asset){current=asset;showImages();$('name').textContent=asset.name;$('study-link').hidden=!asset.study;if(asset.study)$('study-link').href=asset.study;$('status').textContent=asset.reviewStatus;$('note').textContent=asset.reviewNote;$('model-button').disabled=!asset.model?.file;$('front-button').disabled=!asset.front;$('back').hidden=!asset.back;$('empty').hidden=!!asset.back;if(asset.back)$('back').src=asset.back;else $('back').removeAttribute('src');for(const b of $('list').children)b.setAttribute('aria-current',String(b.dataset.id===asset.id));history.replaceState(null,'','#'+asset.id);}
$('source-button').onclick=()=>{frontMode='source';showImages();};$('front-button').onclick=()=>{frontMode='front';showImages();};
$('front').onerror=()=>{$('note').textContent='正面参考读取失败，请重新打开此物件。';};$('back').onerror=()=>{$('back').hidden=true;$('empty').hidden=false;$('empty').textContent='背面图片读取失败，请重新打开此物件。';};
$('model-button').onclick=async()=>{if(!current?.model?.file)return;modelMode=true;$('comparison').hidden=true;$('model-panel').hidden=false;$('model-button').setAttribute('aria-pressed','true');$('source-button').setAttribute('aria-pressed','false');$('front-button').setAttribute('aria-pressed','false');$('model-note').textContent='正在载入模型';const selected=current;try{viewer??=await import('./model-viewer.js').then(m=>m.createViewer($('model-view')));if(!modelMode||selected!==current)return;await viewer.load(selected.model.file,selected.model.yaw||0);if(!modelMode||selected!==current){viewer.pause();return;}$('model-note').textContent='拖动旋转，滚轮缩放；也可使用方向键。';$('model-link').href=selected.model.page;}catch(e){$('model-note').textContent='模型未能载入：'+e.message;}};
$('reset-model').onclick=()=>viewer?.reset();$('turn-model').onclick=()=>viewer?.turn();
try{const response=await fetch('catalog.json');if(!response.ok)throw Error(response.status);catalog=await response.json();$('count').textContent=catalog.length+' 组';for(const asset of catalog){const button=document.createElement('button');button.dataset.id=asset.id;const title=document.createElement('span');title.textContent=asset.name;const status=document.createElement('small');status.textContent=asset.reviewStatus;button.append(title,status);button.onclick=()=>select(asset);$('list').append(button);}select(catalog.find(a=>a.id===location.hash.slice(1))||catalog.find(a=>a.model?.file)||catalog[0]);}catch(e){$('name').textContent='资产记录暂时无法读取';$('note').textContent='请确认本地服务已启动，然后刷新页面。';}
